{
  "name": "Raffle Master - Gerador de Cartelas",
  "description": "Um aplicativo profissional para criação e geração de cartelas de sorteio personalizadas com design glassmorphism e exportação em PDF.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface EventData {
  id: string;
  title: string;
  description: string;
  location: string;
  startDate: string;
  endDate: string;
  drawDate: string;
  value: number;
  prize: string;
  initialSeq: number;
  finalSeq: number;
  createdAt: number;
}

export interface RaffleSlot {
  number: number;
  value: number;
  prize: string;
}

import React, { useState, useEffect } from 'react';
import { 
  PlusCircle, 
  Settings, 
  Printer, 
  Trash2, 
  Calendar, 
  MapPin, 
  DollarSign, 
  Award, 
  ChevronRight,
  ChevronLeft,
  LayoutGrid
} from 'lucide-react';
import { EventData } from './types';
import EventForm from './components/EventForm';
import RafflePreview from './components/RafflePreview';
import { generatePDF } from './services/pdfService';

const App: React.FC = () => {
  const [events, setEvents] = useState<EventData[]>([]);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState<EventData | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // Load from "database" (localStorage)
  useEffect(() => {
    const saved = localStorage.getItem('raffle_events');
    if (saved) {
      setEvents(JSON.parse(saved));
    }
  }, []);

  const saveEvent = (data: EventData) => {
    const updated = [...events, data];
    setEvents(updated);
    localStorage.setItem('raffle_events', JSON.stringify(updated));
    setIsFormOpen(false);
  };

  const deleteEvent = (id: string) => {
    const updated = events.filter(e => e.id !== id);
    setEvents(updated);
    localStorage.setItem('raffle_events', JSON.stringify(updated));
    if (selectedEvent?.id === id) setSelectedEvent(null);
  };

  const handlePrint = async (event: EventData) => {
    setIsProcessing(true);
    try {
      await generatePDF(event);
    } catch (error) {
      console.error("Erro ao gerar PDF:", error);
      alert("Houve um erro ao gerar o PDF. Tente novamente.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen text-slate-100 p-4 md:p-8">
      <header className="max-w-7xl mx-auto mb-10 flex flex-col md:flex-row justify-between items-center gap-6">
        <div>
          <h1 className="text-4xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-purple-400">
            Raffle Master
          </h1>
          <p className="text-slate-400 mt-2">Sistema Profissional de Gerenciamento e Impressão de Cartelas</p>
        </div>
        <button 
          onClick={() => setIsFormOpen(true)}
          className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 transition-colors px-6 py-3 rounded-xl font-semibold shadow-lg shadow-indigo-500/20"
        >
          <PlusCircle size={20} />
          Novo Sorteio
        </button>
      </header>

      <main className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Event List Sidebar */}
        <div className="lg:col-span-4 space-y-4">
          <h2 className="text-xl font-semibold flex items-center gap-2 mb-4">
            <LayoutGrid size={20} />
            Seus Sorteios
          </h2>
          {events.length === 0 ? (
            <div className="glass p-8 rounded-2xl text-center">
              <p className="text-slate-500">Nenhum evento criado ainda.</p>
            </div>
          ) : (
            events.sort((a,b) => b.createdAt - a.createdAt).map(event => (
              <div 
                key={event.id}
                onClick={() => setSelectedEvent(event)}
                className={`glass p-4 rounded-2xl cursor-pointer transition-all border-l-4 group ${
                  selectedEvent?.id === event.id ? 'border-indigo-500 bg-white/10' : 'border-transparent hover:bg-white/5'
                }`}
              >
                <div className="flex justify-between items-start mb-2">
                  <h3 className="font-bold truncate max-w-[200px]">{event.title}</h3>
                  <button 
                    onClick={(e) => { e.stopPropagation(); deleteEvent(event.id); }}
                    className="text-slate-500 hover:text-red-400 transition-colors p-1"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
                <div className="flex flex-col gap-1 text-xs text-slate-400">
                  <span className="flex items-center gap-1"><Calendar size={12} /> Sorteio: {new Date(event.drawDate).toLocaleDateString()}</span>
                  <span className="flex items-center gap-1"><MapPin size={12} /> {event.location}</span>
                </div>
                <div className="mt-3 pt-3 border-t border-white/5 flex justify-between items-center">
                   <span className="text-indigo-400 font-medium">R$ {event.value.toFixed(2)}</span>
                   <ChevronRight className={`transition-transform ${selectedEvent?.id === event.id ? 'rotate-90' : ''}`} size={16} />
                </div>
              </div>
            ))
          )}
        </div>

        {/* Preview and Details Area */}
        <div className="lg:col-span-8">
          {selectedEvent ? (
            <div className="space-y-6">
              <div className="glass p-6 md:p-8 rounded-3xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-8 opacity-5">
                   <Award size={120} />
                </div>

                <div className="flex flex-col md:flex-row justify-between items-start gap-6">
                  <div className="flex-1">
                    <h2 className="text-3xl font-bold mb-2">{selectedEvent.title}</h2>
                    <p className="text-slate-400 mb-6">{selectedEvent.description}</p>

                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div className="bg-white/5 p-3 rounded-xl">
                        <span className="text-[10px] text-slate-500 uppercase block">Local</span>
                        <span className="font-medium flex items-center gap-1"><MapPin size={14} className="text-indigo-400" /> {selectedEvent.location}</span>
                      </div>
                      <div className="bg-white/5 p-3 rounded-xl">
                        <span className="text-[10px] text-slate-500 uppercase block">Data Sorteio</span>
                        <span className="font-medium flex items-center gap-1"><Calendar size={14} className="text-indigo-400" /> {new Date(selectedEvent.drawDate).toLocaleDateString()}</span>
                      </div>
                      <div className="bg-white/5 p-3 rounded-xl">
                        <span className="text-[10px] text-slate-500 uppercase block">Valor Un.</span>
                        <span className="font-medium flex items-center gap-1 text-green-400"><DollarSign size={14} /> {selectedEvent.value.toFixed(2)}</span>
                      </div>
                      <div className="bg-white/5 p-3 rounded-xl">
                        <span className="text-[10px] text-slate-500 uppercase block">Prêmio</span>
                        <span className="font-medium flex items-center gap-1 text-yellow-400"><Award size={14} /> {selectedEvent.prize}</span>
                      </div>
                    </div>
                  </div>

                  <div className="flex flex-col gap-3 w-full md:w-auto">
                    <button 
                      onClick={() => handlePrint(selectedEvent)}
                      disabled={isProcessing}
                      className="flex items-center justify-center gap-2 bg-white text-slate-900 px-6 py-3 rounded-xl font-bold hover:bg-slate-200 transition-colors disabled:opacity-50"
                    >
                      {isProcessing ? 'Processando...' : <><Printer size={20} /> Gerar Cartelas PDF</>}
                    </button>
                    <div className="text-center text-xs text-slate-500">
                      Sequência: {selectedEvent.initialSeq} até {selectedEvent.finalSeq}
                    </div>
                  </div>
                </div>
              </div>

              {/* Visualization */}
              <div className="glass p-6 rounded-3xl">
                <h3 className="text-lg font-semibold mb-6 flex items-center gap-2">
                  <LayoutGrid size={18} className="text-indigo-400" />
                  Visualização das Cartelas
                </h3>
                <RafflePreview event={selectedEvent} />
              </div>
            </div>
          ) : (
            <div className="glass h-full min-h-[400px] flex flex-col items-center justify-center p-8 rounded-3xl text-center border-dashed border-white/10">
              <div className="bg-white/5 p-6 rounded-full mb-4">
                <Settings size={48} className="text-slate-600" />
              </div>
              <h2 className="text-2xl font-bold text-slate-400">Selecione um sorteio para visualizar</h2>
              <p className="text-slate-500 max-w-sm mt-2">Clique em um evento na barra lateral ou crie um novo para começar a gerar suas cartelas.</p>
            </div>
          )}
        </div>
      </main>

      {/* Modal Form */}
      {isFormOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
          <div className="w-full max-w-2xl">
             <EventForm 
               onSave={saveEvent} 
               onClose={() => setIsFormOpen(false)} 
             />
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { X, Save, Calendar, MapPin, DollarSign, Award, Hash } from 'lucide-react';
import { EventData } from '../types';

interface EventFormProps {
  onSave: (data: EventData) => void;
  onClose: () => void;
}

const EventForm: React.FC<EventFormProps> = ({ onSave, onClose }) => {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    location: '',
    startDate: '',
    endDate: '',
    drawDate: '',
    value: 5.00,
    prize: 'PIX R$ 500',
    initialSeq: 1,
    finalSeq: 100
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.drawDate) return;

    const newEvent: EventData = {
      ...formData,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    onSave(newEvent);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'number' ? parseFloat(value) : value
    }));
  };

  return (
    <div className="glass rounded-3xl shadow-2xl overflow-hidden border border-white/20">
      <div className="p-6 border-b border-white/10 flex justify-between items-center bg-white/5">
        <h2 className="text-2xl font-bold text-white flex items-center gap-2">
          <Settings className="text-indigo-400" />
          Configurar Sorteio
        </h2>
        <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
          <X size={24} />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="col-span-2 space-y-2">
            <label className="text-sm font-medium text-slate-300">Título do Evento</label>
            <input 
              required
              name="title"
              value={formData.title}
              onChange={handleChange}
              placeholder="Ex: Rifa Beneficente"
              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-white placeholder:text-slate-600"
            />
          </div>

          <div className="col-span-2 space-y-2">
            <label className="text-sm font-medium text-slate-300">Descrição</label>
            <textarea 
              name="description"
              value={formData.description}
              onChange={handleChange}
              rows={2}
              placeholder="Descreva o propósito do sorteio..."
              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-white placeholder:text-slate-600"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-slate-300 flex items-center gap-2">
              <MapPin size={14} className="text-indigo-400" /> Local
            </label>
            <input 
              name="location"
              value={formData.location}
              onChange={handleChange}
              placeholder="Cidade ou Plataforma"
              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-white"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-slate-300 flex items-center gap-2">
              <Calendar size={14} className="text-indigo-400" /> Data do Sorteio
            </label>
            <input 
              type="date"
              required
              name="drawDate"
              value={formData.drawDate}
              onChange={handleChange}
              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-white"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-slate-300 flex items-center gap-2">
              <DollarSign size={14} className="text-indigo-400" /> Valor Unidade
            </label>
            <input 
              type="number"
              step="0.01"
              name="value"
              value={formData.value}
              onChange={handleChange}
              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-white"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-slate-300 flex items-center gap-2">
              <Award size={14} className="text-indigo-400" /> Prêmio Principal
            </label>
            <input 
              name="prize"
              value={formData.prize}
              onChange={handleChange}
              placeholder="Ex: Carro 0km"
              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-white"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-slate-300 flex items-center gap-2">
              <Hash size={14} className="text-indigo-400" /> Sequência Inicial
