        <div className="pt-6 border-t border-white/10 flex gap-4">
          <button 
            type="button"
            onClick={onClose}
            className="flex-1 py-4 bg-white/5 hover:bg-white/10 text-white rounded-2xl font-semibold transition-all"
          >
            Cancelar
          </button>
          <button 
            type="submit"
            className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-xl shadow-indigo-600/20 transition-all"
          >
            <Save size={20} />
            Salvar e Gerar
          </button>
        </div>
      </form>
    </div>
  );
};

export default EventForm;

import React, { useState } from 'react';
import { EventData } from '../types';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface RafflePreviewProps {
  event: EventData;
}

const RafflePreview: React.FC<RafflePreviewProps> = ({ event }) => {
  const [page, setPage] = useState(0);
  const slotsPerPage = 25;
  const totalSlots = event.finalSeq - event.initialSeq + 1;
  const totalPages = Math.ceil(totalSlots / slotsPerPage);

  const startIdx = page * slotsPerPage;
  const currentSlots = Array.from({ length: slotsPerPage }, (_, i) => {
    const num = event.initialSeq + startIdx + i;
    return num <= event.finalSeq ? num : null;
  });

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
        {currentSlots.map((num, idx) => (
          num ? (
            <div key={idx} className="bg-white/5 border border-white/10 rounded-xl p-3 flex flex-col items-center justify-center aspect-square transition-transform hover:scale-105 hover:bg-white/10 cursor-default">
              <span className="text-3xl font-black text-white mb-1 leading-none">{num}</span>
              <div className="w-full h-px bg-white/10 my-2"></div>
              <div className="text-[8px] text-slate-400 space-y-1 w-full uppercase">
                <div className="flex justify-between"><span>Nome:</span> <span className="border-b border-white/20 w-8"></span></div>
                <div className="flex justify-between"><span>Cel:</span> <span className="border-b border-white/20 w-8"></span></div>
                <div className="text-indigo-400 font-bold mt-1">R$ {event.value.toFixed(2)}</div>
              </div>
            </div>
          ) : (
            <div key={idx} className="bg-black/20 border border-white/5 rounded-xl aspect-square opacity-20"></div>
          )
        ))}
      </div>

      <div className="flex justify-between items-center bg-white/5 p-3 rounded-2xl">
        <button 
          onClick={() => setPage(p => Math.max(0, p - 1))}
          disabled={page === 0}
          className="p-2 hover:bg-white/10 rounded-xl disabled:opacity-30 transition-colors"
        >
          <ChevronLeft />
        </button>
        <span className="text-sm font-medium text-slate-400">
          Página <span className="text-white">{page + 1}</span> de <span className="text-white">{totalPages}</span>
        </span>
        <button 
          onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))}
          disabled={page === totalPages - 1}
          className="p-2 hover:bg-white/10 rounded-xl disabled:opacity-30 transition-colors"
        >
          <ChevronRight />
        </button>
      </div>
    </div>
  );
};

export default RafflePreview;

import { jsPDF } from 'jspdf';
import { EventData } from '../types';

export const generatePDF = async (event: EventData) => {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4'
  });

  const slotsPerPage = 25;
  const totalSlots = event.finalSeq - event.initialSeq + 1;
  const totalPages = Math.ceil(totalSlots / slotsPerPage);

  const margin = 10;
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const contentWidth = pageWidth - (margin * 2);
  const contentHeight = pageHeight - (margin * 2) - 40; // 40mm for header

  const gridCols = 5;
  const gridRows = 5;
  const cellWidth = contentWidth / gridCols;
  const cellHeight = contentHeight / gridRows;

  for (let p = 0; p < totalPages; p++) {
    if (p > 0) doc.addPage();

    // --- Header ---
    doc.setFillColor(31, 27, 75); // Indigo-950
    doc.rect(0, 0, pageWidth, 40, 'F');

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.setFont('helvetica', 'bold');
    doc.text(event.title.toUpperCase(), margin, 15);

    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    const descLines = doc.splitTextToSize(event.description, contentWidth - 60);
    doc.text(descLines, margin, 22);

    // Info boxes in header
    doc.setFontSize(8);
    doc.setTextColor(200, 200, 200);
    doc.text(`LOCAL: ${event.location.toUpperCase()}`, margin, 35);
    doc.text(`SORTEIO: ${new Date(event.drawDate).toLocaleDateString()}`, margin + 50, 35);
    doc.text(`VALOR: R$ ${event.value.toFixed(2)}`, margin + 100, 35);
    doc.text(`PRÊMIO: ${event.prize.toUpperCase()}`, margin + 140, 35);

    // --- Grid ---
    const startY = 45;
    for (let i = 0; i < slotsPerPage; i++) {
      const slotNum = event.initialSeq + (p * slotsPerPage) + i;
      if (slotNum > event.finalSeq) break;

      const row = Math.floor(i / gridCols);
      const col = i % gridCols;
      const x = margin + (col * cellWidth);
      const y = startY + (row * cellHeight);

      // Cell Border
      doc.setDrawColor(200, 200, 200);
      doc.rect(x + 1, y + 1, cellWidth - 2, cellHeight - 2);

      // Number
      doc.setTextColor(0, 0, 0);
      doc.setFontSize(28);
      doc.setFont('helvetica', 'bold');
      const numWidth = doc.getTextWidth(slotNum.toString());
      doc.text(slotNum.toString(), x + (cellWidth / 2) - (numWidth / 2), y + 15);

      // Lines for Name and Cel
      doc.setFontSize(8);
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(100, 100, 100);

      const fieldX = x + 5;
      const fieldW = cellWidth - 10;

      doc.text("Nome:", fieldX, y + 22);
      doc.setDrawColor(220, 220, 220);
      doc.line(fieldX + 10, y + 22, fieldX + fieldW, y + 22);

      doc.text("Cel:", fieldX, y + 28);
      doc.line(fieldX + 10, y + 28, fieldX + fieldW, y + 28);

      // Price and Prize info
      doc.setFontSize(7);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(50, 50, 50);
      doc.text(`Valor: R$ ${event.value.toFixed(2)}`, fieldX, y + 34);
      doc.setFontSize(6);
      doc.text(`Premio: ${event.prize}`, fieldX, y + 38);
    }

    // Page number footer
    doc.setFontSize(8);
    doc.setTextColor(150, 150, 150);
    doc.text(`Página ${p + 1} de ${totalPages}`, pageWidth - 30, pageHeight - 5);
  }

  doc.save(`cartelas-${event.title.toLowerCase().replace(/\s+/g, '-')}.pdf`);
};

