import { jsPDF } from 'jspdf';
import { EventData } from '../types';

export const generatePDF = async (event: EventData) => {
  // Inicialização robusta do jsPDF
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4'
  });

  const slotsPerPage = 25;
  const totalSlots = event.finalSeq - event.initialSeq + 1;
  const totalPages = Math.ceil(totalSlots / slotsPerPage);

  const margin = 10;
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const contentWidth = pageWidth - (margin * 2);
  const headerHeight = 35;
  const contentHeight = pageHeight - (margin * 2) - headerHeight;

  const gridCols = 5;
  const gridRows = 5;
  const cellWidth = contentWidth / gridCols;
  const cellHeight = contentHeight / gridRows;

  // Formatação de moeda brasileira
  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  for (let p = 0; p < totalPages; p++) {
    if (p > 0) doc.addPage();

    // --- Cabeçalho do PDF ---
    doc.setFillColor(240, 240, 240);
    doc.rect(margin, margin, contentWidth, headerHeight - 5, 'F');

    doc.setTextColor(0, 0, 0);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(16);
    doc.text(event.title.toUpperCase(), margin + 5, margin + 10);

    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    doc.text(`Local: ${event.location} | Data Sorteio: ${new Date(event.drawDate).toLocaleDateString()}`, margin + 5, margin + 18);

    doc.setFont('helvetica', 'bold');
    doc.text(`PRÊMIO: ${event.prize.toUpperCase()}`, margin + 5, margin + 25);
    doc.text(`VALOR: R$ ${formatCurrency(event.value)}`, margin + 120, margin + 25);

    // --- Grade de Cartelas ---
    const startY = margin + headerHeight;

    for (let i = 0; i < slotsPerPage; i++) {
      const slotNum = event.initialSeq + (p * slotsPerPage) + i;
      if (slotNum > event.finalSeq) break;

      const row = Math.floor(i / gridCols);
      const col = i % gridCols;
      const x = margin + (col * cellWidth);
      const y = startY + (row * cellHeight);

      // Desenhar Cartela (Estilo do Anexo)
      doc.setDrawColor(180, 180, 180);
      doc.setLineWidth(0.2);
      // Retângulo com cantos levemente arredondados (simulado)
      doc.roundedRect(x + 1, y + 1, cellWidth - 2, cellHeight - 2, 3, 3, 'S');

      // Número Grande
      doc.setTextColor(40, 40, 40);
      doc.setFontSize(26);
      doc.setFont('helvetica', 'bold');
      const numStr = slotNum.toString();
      const numWidth = doc.getTextWidth(numStr);
      doc.text(numStr, x + (cellWidth / 2) - (numWidth / 2), y + 12);

      // Campos Nome e Cel
      doc.setFontSize(10);
      doc.setTextColor(0, 0, 0);
      doc.text("Nome:", x + 4, y + 20);
      doc.text("Cel:", x + 4, y + 26);

      // Linhas pontilhadas/sutis para preenchimento
      doc.setDrawColor(220, 220, 220);
      doc.line(x + 16, y + 20, x + cellWidth - 5, y + 20);
      doc.line(x + 12, y + 26, x + cellWidth - 5, y + 26);

      // Informações de Rodapé da Cartela
      doc.setFontSize(8);
      doc.setFont('helvetica', 'normal');
      doc.text(`Valor: ${formatCurrency(event.value)}`, x + 4, y + 33);
      doc.text(`Premio: ${event.prize}`, x + 4, y + 37);
    }

    // Rodapé da página
    doc.setFontSize(7);
    doc.setTextColor(150, 150, 150);
    doc.text(`Gerado por Raffle Master - Página ${p + 1} de ${totalPages}`, margin, pageHeight - 5);
  }

  doc.save(`cartelas-${event.title.toLowerCase().replace(/\s+/g, '-')}.pdf`);
};

