        <button 
          onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))}
          disabled={page === totalPages - 1}
          className="p-2 hover:bg-white/10 rounded-xl disabled:opacity-30 transition-colors text-white"
        >
          <ChevronRight />
        </button>
      </div>
    </div>
  );
};

