import { jsPDF } from 'jspdf';
import { EventData } from '../types';

export const generatePDF = async (event: EventData) => {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4'
  });

  const slotsPerPage = 25;
  const totalSlots = event.finalSeq - event.initialSeq + 1;
  const totalPages = Math.ceil(totalSlots / slotsPerPage);

  const margin = 10;
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const contentWidth = pageWidth - (margin * 2);

  // Altura do cabeçalho aumentada para acomodar a descrição
  const headerHeight = 45; 
  const spacing = 5;
  const gridStartY = margin + headerHeight + spacing;
  const gridHeight = pageHeight - margin - gridStartY;

  const gridCols = 5;
  const gridRows = 5;
  const cellWidth = contentWidth / gridCols;
  const cellHeight = gridHeight / gridRows;

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  for (let p = 0; p < totalPages; p++) {
    if (p > 0) doc.addPage();

    // --- Cabeçalho ---
    doc.setFillColor(245, 245, 247);
    doc.rect(margin, margin, contentWidth, headerHeight, 'F');

    // Título
    doc.setTextColor(20, 20, 40);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(14);
    doc.text(event.title.toUpperCase(), margin + 5, margin + 8);

    // Descrição (com quebra automática de linha)
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(60, 60, 60);
    const descLines = doc.splitTextToSize(event.description || "Sem descrição disponível.", contentWidth - 10);
    doc.text(descLines, margin + 5, margin + 13);

    // Faixa de informações rápidas no pé do cabeçalho
    const infoY = margin + headerHeight - 5;
    doc.setFontSize(7);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(80, 80, 100);
    doc.text(`LOCAL: ${event.location.toUpperCase()}`, margin + 5, infoY);
    doc.text(`SORTEIO: ${new Date(event.drawDate).toLocaleDateString()}`, margin + 60, infoY);
    doc.text(`VALOR: R$ ${formatCurrency(event.value)}`, margin + 110, infoY);
    doc.text(`PRÊMIO: ${event.prize.toUpperCase()}`, margin + 150, infoY);

    // --- Grade de Cartelas ---
    for (let i = 0; i < slotsPerPage; i++) {
      const slotNum = event.initialSeq + (p * slotsPerPage) + i;
      if (slotNum > event.finalSeq) break;

      const row = Math.floor(i / gridCols);
      const col = i % gridCols;
      const x = margin + (col * cellWidth);
      const y = gridStartY + (row * cellHeight);

      // Borda da Cartela
      doc.setDrawColor(200, 200, 200);
      doc.setLineWidth(0.15);
      doc.roundedRect(x + 1, y + 1, cellWidth - 2, cellHeight - 2, 2, 2, 'S');

      // Número Centralizado
      doc.setTextColor(30, 30, 30);
      doc.setFontSize(22);
      doc.setFont('helvetica', 'bold');
      const numStr = slotNum.toString();
      const numWidth = doc.getTextWidth(numStr);
      doc.text(numStr, x + (cellWidth / 2) - (numWidth / 2), y + 10);

      // Campos Nome e Cel
      doc.setFontSize(8);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(0, 0, 0);
      doc.text("Nome:", x + 4, y + 18);
      doc.text("Cel:", x + 4, y + 24);

      // Linhas de Preenchimento
      doc.setDrawColor(230, 230, 230);
      doc.line(x + 14, y + 18, x + cellWidth - 4, y + 18);
      doc.line(x + 10, y + 24, x + cellWidth - 4, y + 24);

      // Informações de Rodapé da Cartela (Compactas)
      doc.setFontSize(6.5);
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(100, 100, 100);
      doc.text(`Valor: R$ ${formatCurrency(event.value)}`, x + 4, y + cellHeight - 7);

      const prizeText = `Premio: ${event.prize}`;
      const prizeLines = doc.splitTextToSize(prizeText, cellWidth - 8);
      doc.text(prizeLines, x + 4, y + cellHeight - 4);
    }

    // Rodapé da Página
    doc.setFontSize(6);
    doc.setTextColor(180, 180, 180);
    doc.text(`Página ${p + 1} de ${totalPages} | Gerado em ${new Date().toLocaleString()}`, margin, pageHeight - 4);
  }

  doc.save(`cartelas-${event.title.toLowerCase().replace(/\s+/g, '-')}.pdf`);
};

import { jsPDF } from 'jspdf';
import { EventData } from '../types';

export const generatePDF = async (event: EventData) => {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4'
  });

  const slotsPerPage = 25;
  const totalSlots = event.finalSeq - event.initialSeq + 1;
  const totalPages = Math.ceil(totalSlots / slotsPerPage);

  const margin = 10;
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const contentWidth = pageWidth - (margin * 2);

  // Cabeçalho significativamente maior para dar o ar "profissional" solicitado
  const headerHeight = 60; 
  const spacing = 4;
  const gridStartY = margin + headerHeight + spacing;
  const gridHeight = pageHeight - margin - gridStartY - 5; // Folga no fundo

  const gridCols = 5;
  const gridRows = 5;
  const cellWidth = contentWidth / gridCols;
  const cellHeight = gridHeight / gridRows;

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // Nota sobre emojis: jsPDF padrão não suporta emojis. 
  // Vou remover caracteres não-ASCII para evitar que o PDF quebre ou mostre quadrados.
  const cleanText = (text: string) => text.replace(/[^\x00-\x7F]/g, "").trim();

  for (let p = 0; p < totalPages; p++) {
    if (p > 0) doc.addPage();

    // --- Estética do Cabeçalho ---
    doc.setFillColor(30, 32, 54); // Tom escuro elegante (indigo-900)
    doc.roundedRect(margin, margin, contentWidth, headerHeight, 3, 3, 'F');

    // Título Grande e Impactante
    doc.setTextColor(255, 255, 255);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(18);
    doc.text(cleanText(event.title).toUpperCase(), margin + 8, margin + 12);

    // Linha divisória sutil
    doc.setDrawColor(60, 65, 100);
    doc.line(margin + 8, margin + 15, margin + contentWidth - 8, margin + 15);

    // Descrição (com quebra automática)
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(200, 200, 220);
    const descLines = doc.splitTextToSize(cleanText(event.description) || "Sem descrição disponível.", contentWidth - 16);
    doc.text(descLines, margin + 8, margin + 22);

    // Box de Informações Rápidas (Pé do cabeçalho)
    const boxY = margin + headerHeight - 12;
    doc.setFillColor(45, 48, 80);
    doc.roundedRect(margin + 5, boxY - 4, contentWidth - 10, 10, 2, 2, 'F');

    doc.setFontSize(7.5);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(150, 160, 255); // Azul claro

    doc.text(`LOCAL: ${cleanText(event.location).toUpperCase()}`, margin + 10, boxY + 2);
    doc.text(`SORTEIO: ${new Date(event.drawDate).toLocaleDateString()}`, margin + 70, boxY + 2);
    doc.text(`VALOR: R$ ${formatCurrency(event.value)}`, margin + 115, boxY + 2);
    doc.text(`PRÊMIO: ${cleanText(event.prize).toUpperCase()}`, margin + 155, boxY + 2);

    // --- Grade de Cartelas ---
    for (let i = 0; i < slotsPerPage; i++) {
      const slotNum = event.initialSeq + (p * slotsPerPage) + i;
      if (slotNum > event.finalSeq) break;

      const row = Math.floor(i / gridCols);
      const col = i % gridCols;
      const x = margin + (col * cellWidth);
      const y = gridStartY + (row * cellHeight);

      // Borda da Cartela (Estilo clean)
      doc.setDrawColor(220, 220, 225);
      doc.setLineWidth(0.2);
      doc.roundedRect(x + 1, y + 1, cellWidth - 2, cellHeight - 2, 3, 3, 'S');

      // NÚMERO GIGANTE (Foco do usuário)
      doc.setTextColor(20, 20, 30);
      doc.setFontSize(32); // Aumentado para máximo impacto
      doc.setFont('helvetica', 'bold');
      const numStr = slotNum.toString();
      const numWidth = doc.getTextWidth(numStr);
      doc.text(numStr, x + (cellWidth / 2) - (numWidth / 2), y + 13);

      // Linhas de identificação (Nome/Cel)
      doc.setFontSize(8.5);
      doc.setTextColor(0, 0, 0);
      doc.text("Nome:", x + 4, y + 21);
      doc.text("Cel:", x + 4, y + 27);

      doc.setDrawColor(235, 235, 240);
      doc.line(x + 14, y + 21, x + cellWidth - 4, y + 21);
      doc.line(x + 10, y + 27, x + cellWidth - 4, y + 27);

      // Rodapé da Cartela (Info de segurança/validade)
      doc.setFontSize(6.5);
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(120, 120, 130);
      doc.text(`Valor: R$ ${formatCurrency(event.value)}`, x + 4, y + cellHeight - 7);

      const prizeText = `Premio: ${cleanText(event.prize)}`;
      const prizeLines = doc.splitTextToSize(prizeText, cellWidth - 8);
      doc.text(prizeLines, x + 4, y + cellHeight - 4);
    }

    // Paginação
    doc.setFontSize(7);
    doc.setTextColor(180, 180, 190);
    doc.text(`Página ${p + 1} de ${totalPages} | Raffle Master Professional`, margin, pageHeight - 5);
  }

  doc.save(`RAFA-${event.title.toUpperCase().replace(/\s+/g, '-')}.pdf`);
};

import React, { useState } from 'react';
import { EventData } from '../types';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface RafflePreviewProps {
  event: EventData;
}

const RafflePreview: React.FC<RafflePreviewProps> = ({ event }) => {
  const [page, setPage] = useState(0);
  const slotsPerPage = 25;
  const totalSlots = event.finalSeq - event.initialSeq + 1;
  const totalPages = Math.ceil(totalSlots / slotsPerPage);

  const startIdx = page * slotsPerPage;
  const currentSlots = Array.from({ length: slotsPerPage }, (_, i) => {
    const num = event.initialSeq + startIdx + i;
    return num <= event.finalSeq ? num : null;
  });

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4">
        {currentSlots.map((num, idx) => (
          num ? (
            <div key={idx} className="bg-white rounded-[2rem] p-5 flex flex-col items-start justify-between aspect-square transition-all hover:shadow-2xl hover:-translate-y-1 border border-slate-200 shadow-sm text-slate-900 overflow-hidden relative group">
              {/* Número no topo centralizado - GIGANTE */}
              <div className="w-full text-center mt-1">
                <span className="text-6xl font-black text-slate-900 leading-none tracking-tighter">{num}</span>
              </div>

              {/* Corpo da cartela com inputs simulados */}
              <div className="w-full space-y-3 mb-2">
                <div className="flex flex-col gap-1">
                  <span className="text-[10px] uppercase font-black text-slate-400 leading-tight">Nome participante</span>
                  <div className="h-px w-full bg-slate-100"></div>
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-[10px] uppercase font-black text-slate-400 leading-tight">Celular</span>
                  <div className="h-px w-full bg-slate-100"></div>
                </div>
              </div>

              {/* Rodapé da cartela */}
              <div className="w-full text-[10px] text-slate-500 font-bold leading-tight pt-2 border-t border-slate-50">
                <div className="flex justify-between items-center mb-0.5">
                  <span>Valor: R$ {formatCurrency(event.value)}</span>
                </div>
                <div className="truncate opacity-70">Prêmio: {event.prize}</div>
              </div>
            </div>
          ) : (
            <div key={idx} className="bg-white/5 border border-white/5 rounded-[2rem] aspect-square opacity-5"></div>
          )
        ))}
      </div>

      <div className="flex justify-between items-center bg-white/[0.03] p-6 rounded-[2rem] border border-white/5 shadow-inner">
        <button 
          onClick={() => setPage(p => Math.max(0, p - 1))}
          disabled={page === 0}
          className="flex items-center gap-2 px-6 py-3 bg-white/5 hover:bg-white/10 rounded-2xl disabled:opacity-20 transition-all text-white font-bold text-sm"
        >
          <ChevronLeft size={18} /> Anterior
        </button>
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Visualização</span>
          <span className="text-sm font-bold text-slate-300">
            Página <span className="text-white text-lg font-black">{page + 1}</span> de <span className="text-white text-lg font-black">{totalPages}</span>
          </span>
        </div>
        <button 
          onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))}
          disabled={page === totalPages - 1}
          className="flex items-center gap-2 px-6 py-3 bg-white/5 hover:bg-white/10 rounded-2xl disabled:opacity-20 transition-all text-white font-bold text-sm"
        >
          Próxima <ChevronRight size={18} />
        </button>
      </div>
    </div>
  );
};

export default RafflePreview;

import React, { useState, useEffect } from 'react';
