import { jsPDF } from 'jspdf';
import { EventData } from '../types';

export const generatePDF = async (event: EventData) => {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4'
  });

  const slotsPerPage = 25;
  const totalSlots = event.finalSeq - event.initialSeq + 1;
  const totalPages = Math.ceil(totalSlots / slotsPerPage);

  const margin = 10;
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const contentWidth = pageWidth - (margin * 2);

  // Cabeçalho expandido para 85mm para caber todas as informações confortavelmente
  const headerHeight = 85; 
  const spacing = 5;
  const gridStartY = margin + headerHeight + spacing;
  const gridHeight = pageHeight - margin - gridStartY - 5;

  const gridCols = 5;
  const gridRows = 5;
  const cellWidth = contentWidth / gridCols;
  const cellHeight = gridHeight / gridRows;

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // Nota: jsPDF padrão usa fontes core que não suportam emojis complexos.
  // Limpamos o texto para evitar caracteres quebrados, mas mantemos a estrutura.
  const cleanText = (text: string) => text.replace(/[^\x00-\x7F]/g, "").trim();

  for (let p = 0; p < totalPages; p++) {
    if (p > 0) doc.addPage();

    // --- Estética do Cabeçalho (Fundo Claro/Suave) ---
    doc.setFillColor(248, 250, 252); // Tom de fundo muito claro (slate-50)
    doc.setDrawColor(226, 232, 240); // Borda suave (slate-200)
    doc.roundedRect(margin, margin, contentWidth, headerHeight, 4, 4, 'FD');

    // Título Principal - Grande e Escuro
    doc.setTextColor(15, 23, 42); // slate-900
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(22);
    const titleText = cleanText(event.title).toUpperCase() || "SORTEIO";
    doc.text(titleText, margin + 8, margin + 15);

    // Linha Decorativa
    doc.setDrawColor(79, 70, 229); // indigo-600
    doc.setLineWidth(1);
    doc.line(margin + 8, margin + 18, margin + 40, margin + 18);

    // Descrição Detalhada
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(51, 65, 85); // slate-700
    const descLines = doc.splitTextToSize(event.description || "Sem descrição informada.", contentWidth - 16);
    doc.text(descLines, margin + 8, margin + 25);

    // Box de Informações de Rodapé do Cabeçalho
    const boxY = margin + headerHeight - 18;
    doc.setFillColor(241, 245, 249); // slate-100
    doc.roundedRect(margin + 5, boxY, contentWidth - 10, 14, 2, 2, 'F');

    doc.setFontSize(8.5);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(30, 41, 59); // slate-800

    // Colunas de Informação
    const col1 = margin + 10;
    const col2 = margin + 65;
    const col3 = margin + 110;
    const col4 = margin + 150;

    doc.text("LOCAL:", col1, boxY + 5);
    doc.setFont('helvetica', 'normal');
    doc.text(cleanText(event.location).toUpperCase() || "-", col1, boxY + 10);

    doc.setFont('helvetica', 'bold');
    doc.text("DATA SORTEIO:", col2, boxY + 5);
    doc.setFont('helvetica', 'normal');
    doc.text(new Date(event.drawDate).toLocaleDateString(), col2, boxY + 10);

    doc.setFont('helvetica', 'bold');
    doc.text("VALOR UNIT.:", col3, boxY + 5);
    doc.setTextColor(22, 163, 74); // emerald-600
    doc.text(`R$ ${formatCurrency(event.value)}`, col3, boxY + 10);

    doc.setTextColor(30, 41, 59);
    doc.setFont('helvetica', 'bold');
    doc.text("PRÊMIO:", col4, boxY + 5);
    doc.setFont('helvetica', 'normal');
    const prizeLines = doc.splitTextToSize(cleanText(event.prize).toUpperCase() || "-", contentWidth - 155);
    doc.text(prizeLines, col4, boxY + 10);

    // --- Grade de Cartelas ---
    for (let i = 0; i < slotsPerPage; i++) {
      const slotNum = event.initialSeq + (p * slotsPerPage) + i;
      if (slotNum > event.finalSeq) break;

      const row = Math.floor(i / gridCols);
      const col = i % gridCols;
      const x = margin + (col * cellWidth);
      const y = gridStartY + (row * cellHeight);

      // Borda da Cartela
      doc.setDrawColor(203, 213, 225); // slate-300
      doc.setLineWidth(0.2);
      doc.roundedRect(x + 1, y + 1, cellWidth - 2, cellHeight - 2, 3, 3, 'S');

      // NÚMERO GIGANTE
      doc.setTextColor(15, 23, 42); // slate-900
      doc.setFontSize(36); 
      doc.setFont('helvetica', 'bold');
      const numStr = slotNum.toString();
      const numWidth = doc.getTextWidth(numStr);
      doc.text(numStr, x + (cellWidth / 2) - (numWidth / 2), y + 14);

      // Campos Nome e Cel
      doc.setFontSize(9);
      doc.setTextColor(71, 85, 105); // slate-600
      doc.text("NOME:", x + 4, y + 23);
      doc.text("CEL:", x + 4, y + 29);

      doc.setDrawColor(241, 245, 249); // slate-100
      doc.line(x + 16, y + 23, x + cellWidth - 4, y + 23);
      doc.line(x + 12, y + 29, x + cellWidth - 4, y + 29);

      // Info Rodapé Cartela
      doc.setFontSize(7);
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(100, 116, 139); // slate-500
      doc.text(`VALOR: R$ ${formatCurrency(event.value)}`, x + 4, y + cellHeight - 7);

      const smallPrize = cleanText(event.prize);
      const prizeLinesCartela = doc.splitTextToSize(`PRÊMIO: ${smallPrize}`, cellWidth - 8);
      doc.text(prizeLinesCartela, x + 4, y + cellHeight - 4);
    }

    // Paginação Rodapé
    doc.setFontSize(7);
    doc.setTextColor(148, 163, 184); // slate-400
    doc.text(`Página ${p + 1} de ${totalPages} | Documento Oficial Raffle Master`, margin, pageHeight - 5);
  }

  doc.save(`RIFA-${event.title.toUpperCase().replace(/\s+/g, '-')}.pdf`);
};

import { jsPDF } from 'jspdf';
import { EventData } from '../types';

export const generatePDF = async (event: EventData) => {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4'
  });

  const slotsPerPage = 25;
  const totalSlots = event.finalSeq - event.initialSeq + 1;
  const totalPages = Math.ceil(totalSlots / slotsPerPage);

  const margin = 10;
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const contentWidth = pageWidth - (margin * 2);

  // Cabeçalho expandido para 110mm para garantir que textos longos não sobreponham
  const headerHeight = 110; 
  const spacing = 5;
  const gridStartY = margin + headerHeight + spacing;
  const gridHeight = pageHeight - margin - gridStartY - 5;

  const gridCols = 5;
  const gridRows = 5;
  const cellWidth = contentWidth / gridCols;
  const cellHeight = gridHeight / gridRows;

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  /**
   * Função para limpar o texto: 
   * 1. Normaliza para remover acentos (evita caracteres estranhos no jsPDF sem fontes customizadas)
   * 2. Remove emojis e qualquer caractere não-ASCII
   */
  const cleanText = (text: string) => {
    if (!text) return "";
    return text
      .normalize("NFD") // Decompõe acentos
      .replace(/[\u0300-\u036f]/g, "") // Remove os acentos
      .replace(/[^\x20-\x7E]/g, "") // Remove emojis e caracteres especiais não-ASCII
      .trim();
  };

  for (let p = 0; p < totalPages; p++) {
    if (p > 0) doc.addPage();

    // --- Estética do Cabeçalho (Fundo Branco/Transparente) ---
    doc.setFillColor(255, 255, 255); 
    doc.setDrawColor(220, 220, 230); // Borda muito sutil
    doc.roundedRect(margin, margin, contentWidth, headerHeight, 2, 2, 'FD');

    // Título Principal - Grande e com fonte padrão segura
    doc.setTextColor(0, 0, 0);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(24);
    const titleText = cleanText(event.title).toUpperCase() || "RIFA";
    doc.text(titleText, margin + 5, margin + 15);

    // Linha Divisória
    doc.setDrawColor(0, 0, 0);
    doc.setLineWidth(0.8);
    doc.line(margin + 5, margin + 18, margin + 60, margin + 18);

    // Descrição Detalhada - Agora com mais espaço
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    doc.setTextColor(40, 40, 40);
    const descLines = doc.splitTextToSize(cleanText(event.description) || "Descricao nao informada.", contentWidth - 15);
    doc.text(descLines, margin + 5, margin + 28);

    // Painel de Informações Estilo "Box" no final do cabeçalho
    const infoBoxY = margin + headerHeight - 25;
    doc.setFillColor(250, 250, 252);
    doc.roundedRect(margin + 2, infoBoxY, contentWidth - 4, 20, 1, 1, 'F');

    doc.setFontSize(9);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(0, 0, 0);

    // Alinhamento das Colunas para evitar sobreposição (X posições)
    const colX1 = margin + 5;
    const colX2 = margin + 60;
    const colX3 = margin + 105;
    const colX4 = margin + 145;

    // LOCAL
    doc.text("LOCAL:", colX1, infoBoxY + 7);
    doc.setFont('helvetica', 'normal');
    const locationLines = doc.splitTextToSize(cleanText(event.location).toUpperCase() || "-", colX2 - colX1 - 5);
    doc.text(locationLines, colX1, infoBoxY + 13);

    // DATA
    doc.setFont('helvetica', 'bold');
    doc.text("DATA SORTEIO:", colX2, infoBoxY + 7);
    doc.setFont('helvetica', 'normal');
    doc.text(new Date(event.drawDate).toLocaleDateString(), colX2, infoBoxY + 13);

    // VALOR
    doc.setFont('helvetica', 'bold');
    doc.text("VALOR UNIDADE:", colX3, infoBoxY + 7);
    doc.setTextColor(30, 150, 30); // Verde para o valor
    doc.text(`R$ ${formatCurrency(event.value)}`, colX3, infoBoxY + 13);

    // PREMIO
    doc.setTextColor(0, 0, 0);
    doc.setFont('helvetica', 'bold');
    doc.text("PREMIO:", colX4, infoBoxY + 7);
    doc.setFont('helvetica', 'normal');
    const prizeLines = doc.splitTextToSize(cleanText(event.prize).toUpperCase() || "-", contentWidth - (colX4 - margin) - 5);
    doc.text(prizeLines, colX4, infoBoxY + 13);

    // --- Grade de Cartelas ---
    for (let i = 0; i < slotsPerPage; i++) {
      const slotNum = event.initialSeq + (p * slotsPerPage) + i;
      if (slotNum > event.finalSeq) break;

      const row = Math.floor(i / gridCols);
      const col = i % gridCols;
      const x = margin + (col * cellWidth);
      const y = gridStartY + (row * cellHeight);

      // Borda da Cartela
      doc.setDrawColor(180, 180, 180);
      doc.setLineWidth(0.1);
      doc.rect(x + 1, y + 1, cellWidth - 2, cellHeight - 2, 'S');

      // NÚMERO GIGANTE (Aumentado para 42 para máximo destaque)
      doc.setTextColor(0, 0, 0);
      doc.setFontSize(42); 
      doc.setFont('helvetica', 'bold');
      const numStr = slotNum.toString();
      const numWidth = doc.getTextWidth(numStr);
      doc.text(numStr, x + (cellWidth / 2) - (numWidth / 2), y + 15);

      // Campos Nome e Cel
      doc.setFontSize(9);
      doc.setTextColor(0, 0, 0);
      doc.text("NOME:", x + 3, y + 24);
      doc.text("CEL:", x + 3, y + 30);

      // Linhas pontilhadas/suaves para preenchimento
      doc.setDrawColor(220, 220, 220);
      doc.line(x + 15, y + 24, x + cellWidth - 4, y + 24);
      doc.line(x + 12, y + 30, x + cellWidth - 4, y + 30);

      // Info Rodapé Cartela (Compacta)
      doc.setFontSize(7);
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(80, 80, 80);
      doc.text(`Valor: R$ ${formatCurrency(event.value)}`, x + 3, y + cellHeight - 7);

      const smallPrize = cleanText(event.prize);
      const prizeLinesCartela = doc.splitTextToSize(`Premio: ${smallPrize}`, cellWidth - 6);
      doc.text(prizeLinesCartela, x + 3, y + cellHeight - 4);
    }

    // Rodapé de página
    doc.setFontSize(7);
    doc.setTextColor(150, 150, 150);
    doc.text(`Pagina ${p + 1} de ${totalPages} | Gerado por Raffle Master`, margin, pageHeight - 5);
  }

  doc.save(`RIFA-${cleanText(event.title).toUpperCase().replace(/\s+/g, '-')}.pdf`);
};

