  const gridCols = 5;
  const gridRows = 5;
  const cellWidth = contentWidth / gridCols;
  const cellHeight = gridHeight / gridRows;

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  const cleanText = (text: string) => {
    if (!text) return "";
    return text
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "") 
      .replace(/[^\x20-\x7E]/g, "") 
      .trim();
  };

  for (let p = 0; p < totalPages; p++) {
    if (p > 0) doc.addPage();

    // --- Cabeçalho Otimizado ---
    doc.setFillColor(255, 255, 255); 
    doc.setDrawColor(220, 220, 230);
    doc.setLineWidth(0.1);
    doc.roundedRect(margin, margin, contentWidth, headerHeight, 2, 2, 'FD');

    // Título
    doc.setTextColor(0, 0, 0);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(20);
    const titleText = cleanText(event.title).toUpperCase() || "SORTEIO";
    doc.text(titleText, margin + 6, margin + 12);

    // Linha Decorativa
    doc.setDrawColor(0, 0, 0);
    doc.setLineWidth(0.6);
    doc.line(margin + 6, margin + 14, margin + 40, margin + 14);

    // Descrição (Área maior e melhor distribuída)
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(40, 40, 40);
    const descLines = doc.splitTextToSize(cleanText(event.description) || "Sem informacoes adicionais.", contentWidth - 12);
    doc.text(descLines, margin + 6, margin + 22);

    // Painel de Informações compacto
    const infoBoxY = margin + headerHeight - 22;
    const infoBoxHeight = 18;
    doc.setFillColor(248, 250, 252);
    doc.roundedRect(margin + 3, infoBoxY, contentWidth - 6, infoBoxHeight, 1, 1, 'F');

    doc.setFontSize(8);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(70, 70, 80);

    const labelY = infoBoxY + 6;
    const valueY = infoBoxY + 12;

    const colX1 = margin + 6;
    const colX2 = margin + 60;
    const colX3 = margin + 105;
    const colX4 = margin + 145;

    // LOCAL
    doc.text("LOCAL:", colX1, labelY);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(0, 0, 0);
    const locationStr = cleanText(event.location).toUpperCase() || "-";
    const locLines = doc.splitTextToSize(locationStr, colX2 - colX1 - 4);
    doc.text(locLines, colX1, valueY);

    // DATA
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(70, 70, 80);
    doc.text("DATA:", colX2, labelY);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(0, 0, 0);
    doc.text(new Date(event.drawDate).toLocaleDateString(), colX2, valueY);

    // VALOR
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(70, 70, 80);
    doc.text("VALOR:", colX3, labelY);
    doc.setTextColor(20, 140, 20);
    doc.text(`R$ ${formatCurrency(event.value)}`, colX3, valueY);

    // PREMIO
    doc.setTextColor(70, 70, 80);
    doc.setFont('helvetica', 'bold');
    doc.text("PREMIO:", colX4, labelY);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(0, 0, 0);
    const prizeStr = cleanText(event.prize).toUpperCase() || "-";
    const prizeLines = doc.splitTextToSize(prizeStr, contentWidth - (colX4 - margin) - 6);
    doc.text(prizeLines, colX4, valueY);

    // --- Grade de Cartelas ---
    for (let i = 0; i < slotsPerPage; i++) {
      const slotNum = event.initialSeq + (p * slotsPerPage) + i;
      if (slotNum > event.finalSeq) break;

      const row = Math.floor(i / gridCols);
      const col = i % gridCols;
      const x = margin + (col * cellWidth);
      const y = gridStartY + (row * cellHeight);

      // Borda da Cartela (Espaçamento reduzido)
      doc.setDrawColor(210, 210, 220);
      doc.setLineWidth(0.05);
      doc.rect(x + 0.5, y + 0.5, cellWidth - 1, cellHeight - 1, 'S');

      // Número Centralizado
      doc.setTextColor(0, 0, 0);
      doc.setFontSize(34); 
      doc.setFont('helvetica', 'bold');
      const numStr = slotNum.toString();
      const numWidth = doc.getTextWidth(numStr);
      doc.text(numStr, x + (cellWidth / 2) - (numWidth / 2), y + 13);

      // Campos de Preenchimento
      doc.setFontSize(8);
      doc.setFont('helvetica', 'bold');
      doc.text("NOME:", x + 3, y + 21);
      doc.text("CEL:", x + 3, y + 26);

      doc.setDrawColor(235, 235, 235);
      doc.setLineWidth(0.15);
      doc.line(x + 13, y + 21, x + cellWidth - 3, y + 21);
      doc.line(x + 10, y + 26, x + cellWidth - 3, y + 26);

      // Rodapé da Cartela (Reduzido para economizar espaço)
      doc.setFontSize(5.5);
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(110, 110, 110);
      doc.text(`Valor: R$ ${formatCurrency(event.value)}`, x + 3, y + cellHeight - 5.5);

      const prizeCartela = cleanText(event.prize);
      const prizeLinesCartela = doc.splitTextToSize(`Premio: ${prizeCartela}`, cellWidth - 6);
      doc.text(prizeLinesCartela, x + 3, y + cellHeight - 3);
    }

    // Rodapé
    doc.setFontSize(6);
    doc.setTextColor(180, 180, 180);
    doc.text(`Pagina ${p + 1} de ${totalPages} | Raffle Master`, margin, pageHeight - 3);
  }

  doc.save(`RIFA-${cleanText(event.title).toUpperCase().replace(/\s+/g, '-')}.pdf`);
};

