import { PGlite } from '@electric-sql/pglite';
import { EventData } from '../types';

let _pg: any = null;
let _initPromise: Promise<any> | null = null;

const getPg = async () => {
  if (_pg) return _pg;
  if (_initPromise) return _initPromise;

  _initPromise = (async () => {
    try {
      console.log("Iniciando PostgreSQL Local (PGlite)...");

      // Tenta encontrar o construtor correto (pode variar dependendo do empacotamento do esm.sh)
      let PGliteConstructor: any = PGlite;

      // Se PGlite for um módulo com a propriedade PGlite dentro dele
      if (typeof PGliteConstructor !== 'function' && (PGlite as any).PGlite) {
        PGliteConstructor = (PGlite as any).PGlite;
      }

      // Se ainda não for uma função, tenta o .default (comum em ESM)
      if (typeof PGliteConstructor !== 'function' && (PGlite as any).default) {
        PGliteConstructor = (PGlite as any).default;
      }

      if (typeof PGliteConstructor !== 'function') {
        throw new Error("Não foi possível encontrar o construtor do PGlite. Verifique a importação.");
      }

      // Inicializa o banco no IndexedDB
      const pg = new PGliteConstructor('idb://raffle-master-db');

      // Aguarda o banco estar pronto
      if (pg.waitReady) {
        await pg.waitReady;
      }

      // Criação da tabela com SQL puro
      await pg.exec(`
        CREATE TABLE IF NOT EXISTS events (
          id TEXT PRIMARY KEY,
          title TEXT NOT NULL,
          description TEXT,
          location TEXT,
          startDate TEXT,
          endDate TEXT,
          drawDate TEXT NOT NULL,
