const App: React.FC = () => {
  const [events, setEvents] = useState<EventData[]>([]);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState<EventData | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDbLoading, setIsDbLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);
  const [lastConfig, setLastConfig] = useState<Partial<EventData> | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setIsDbLoading(true);
    setDbError(null);
    try {
      const data = await db.getEvents();
      setEvents(data);
      if (data && data.length > 0) {
        setSelectedEvent(data[0]);
        setLastConfig(data[0]);
      }
    } catch (err: any) {
      const msg = err?.message || String(err);
      console.error("Erro no carregamento do BD:", msg);
      setDbError(msg);
    } finally {
      setIsDbLoading(false);
    }
  };

  const saveEvent = async (data: EventData) => {
    try {
      await db.saveEvent(data);
      setEvents(prev => [data, ...prev]);
      setLastConfig(data);
      setIsFormOpen(false);
      setSelectedEvent(data);
    } catch (e) {
      console.error("Erro ao salvar:", e);
      alert("Erro ao gravar no banco SQL local.");
    }
  };

  const deleteEvent = async (id: string) => {
    if(!confirm("Deseja apagar este sorteio do banco local?")) return;
    try {
      await db.deleteEvent(id);
      setEvents(prev => {
        const updated = prev.filter(e => e.id !== id);
        if (selectedEvent?.id === id) {
          setSelectedEvent(updated.length > 0 ? updated[0] : null);
        }
        return updated;
      });
    } catch (e) {
      alert("Erro ao remover do banco.");
    }
  };

  const handlePrint = async (event: EventData) => {
    setIsProcessing(true);
    setTimeout(async () => {
      try {
        await generatePDF(event);
