      ]);
    } catch (error) {
      console.error("Erro ao salvar no SQL:", error);
      throw error;
    }
  },

  async deleteEvent(id: string): Promise<void> {
    try {
      const pg = await getPg();
      if (!pg || typeof pg.query !== 'function') throw new Error("Banco não disponível");
      await pg.query(`DELETE FROM events WHERE id = $1;`, [id]);
    } catch (error) {
      console.error("Erro ao deletar no SQL:", error);
      throw error;
    }
  }
};

