import React, { useState, useEffect, useRef } from 'react';
import { X, Trophy, RefreshCw, PartyPopper, Sparkles } from 'lucide-react';

interface DrawModalProps {
  initialSeq: number;
  finalSeq: number;
  title: string;
  onClose: () => void;
}

const DrawModal: React.FC<DrawModalProps> = ({ initialSeq, finalSeq, title, onClose }) => {
  const [isDrawing, setIsDrawing] = useState(false);
  const [currentNumber, setCurrentNumber] = useState<number | null>(null);
  const [winner, setWinner] = useState<number | null>(null);
  const [history, setHistory] = useState<number[]>([]);
  const timerRef = useRef<number | null>(null);

  const startDraw = () => {
    if (isDrawing) return;

    setIsDrawing(true);
    setWinner(null);
    let duration = 3000; // 3 segundos de animação
    let interval = 50;   // Começa rápido
    const startTime = Date.now();

    const animate = () => {
      const elapsed = Date.now() - startTime;
      const progress = elapsed / duration;

      // Gera número aleatório dentro do intervalo
      const randomNum = Math.floor(Math.random() * (finalSeq - initialSeq + 1)) + initialSeq;
      setCurrentNumber(randomNum);

      if (elapsed < duration) {
        // Desacelera o intervalo conforme o tempo passa (curva exponencial)
        interval = 50 + Math.pow(progress, 3) * 500;
        timerRef.current = window.setTimeout(animate, interval);
      } else {
        // Finaliza o sorteio
        const finalWinner = Math.floor(Math.random() * (finalSeq - initialSeq + 1)) + initialSeq;
        setCurrentNumber(finalWinner);
        setWinner(finalWinner);
        setIsDrawing(false);
        setHistory(prev => [finalWinner, ...prev].slice(0, 5));
      }
    };

    animate();
  };

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, []);

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl">
      <div className="w-full max-w-2xl bg-[#15162b] rounded-[3rem] border border-white/10 shadow-[0_0_100px_rgba(79,70,229,0.2)] overflow-hidden relative">
        {/* Efeito de brilho de fundo */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-indigo-600/20 blur-[120px] rounded-full"></div>

        <div className="relative z-10 p-10 flex flex-col items-center">
          <button 
            onClick={onClose}
            className="absolute top-6 right-6 p-3 bg-white/5 hover:bg-white/10 rounded-2xl text-slate-400 transition-all"
          >
            <X size={24} />
          </button>

          <div className="mb-8 text-center">
            <div className="flex justify-center mb-4">
              <div className="p-4 bg-indigo-500/10 rounded-2xl border border-indigo-500/20">
                <Trophy size={32} className="text-indigo-400" />
              </div>
            </div>
            <h2 className="text-3xl font-black tracking-tighter text-white uppercase">{title}</h2>
            <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.2em] mt-2">Sorteio Aleatório Autorizado</p>
          </div>

          {/* Display do Número */}
          <div className="relative w-72 h-72 flex items-center justify-center mb-10">
            {/* Anéis decorativos */}
            <div className={`absolute inset-0 border-4 border-dashed border-indigo-500/20 rounded-full ${isDrawing ? 'animate-spin' : ''}`} style={{ animationDuration: '10s' }}></div>
            <div className={`absolute inset-4 border-2 border-indigo-500/10 rounded-full ${isDrawing ? 'animate-spin' : ''}`} style={{ animationDuration: '15s', animationDirection: 'reverse' }}></div>

            <div className={`
              text-8xl font-black tracking-tighter transition-all duration-300
              ${winner ? 'scale-125 text-white drop-shadow-[0_0_30px_rgba(99,102,241,0.8)]' : 'text-indigo-400'}
              ${isDrawing ? 'blur-sm opacity-50' : 'blur-0 opacity-100'}
            `}>
              {currentNumber || '???'}
            </div>
          </div>

          {winner ? (
            <div className="text-center animate-in zoom-in duration-500">
              <div className="flex items-center justify-center gap-3 mb-6">
                <PartyPopper className="text-yellow-400" size={32} />
                <h3 className="text-4xl font-black text-white">GANHADOR: {winner}</h3>
                <PartyPopper className="text-yellow-400" size={32} />
              </div>
              <button 
                onClick={startDraw}
                className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 px-8 py-4 rounded-2xl font-black text-sm transition-all shadow-xl shadow-indigo-600/20"
              >
                <RefreshCw size={20} /> SORTEAR NOVAMENTE
              </button>
            </div>
          ) : (
            <button 
              onClick={startDraw}
              disabled={isDrawing}
              className={`
                flex items-center gap-3 px-12 py-6 rounded-[2rem] font-black text-xl transition-all shadow-2xl
                ${isDrawing 
                  ? 'bg-slate-800 text-slate-500 cursor-not-allowed' 
                  : 'bg-white text-indigo-950 hover:scale-105 active:scale-95 shadow-white/10'}
              `}
            >
              {isDrawing ? 'SORTEANDO...' : <><Sparkles size={24} /> INICIAR SORTEIO</>}
            </button>
          )}

          {/* Histórico Simples */}
          {history.length > 0 && (
            <div className="mt-12 w-full max-w-xs">
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest text-center mb-4">Últimos Sorteados</p>
              <div className="flex justify-center gap-3">
                {history.map((num, i) => (
                  <div key={i} className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center font-bold text-slate-400 border border-white/5">
                    {num}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

